"""results.json → the model's markdown page (docs/research/models/brahmacharini-ranker.md)."""

from __future__ import annotations

import json
import sys


def main(path: str) -> None:
    r = json.loads(open(path, encoding="utf-8").read())
    lines = [
        "# Brahmacharini passage ranker (generated)", "",
        "Which passage of the web pages Sati AI read answers the question. Generated by "
        "`python -m sati.webqa.run`; do not edit by hand.", "",
        f"- **Data:** {r['data']}",
        f"- **Questions:** {r['train_questions']} for training ({r['trained_on_questions']} had passages to order), "
        f"{r['test_questions']} held out (NQ's validation questions)",
        f"- **Served:** {'yes' if r['served'] else 'no — the hand-set score stays served'}", "",
        "answer@1 is the share of all held-out questions whose top passage contains a gold answer; a question "
        "whose fetched pages hold no answer counts as a miss.", "",
        "| Ranking | answer@1 | 95% CI |", "|---|---|---|",
    ]
    for name, v in r["answer_at_1"].items():
        lines.append(f"| {name} | {v['rate']:.3f} | {v['ci95'][0]:.3f}–{v['ci95'][1]:.3f} |")
    c = r["ceiling"]
    lines.append(f"| ceiling ({c['meaning']}) | {c['rate']:.3f} | {c['ci95'][0]:.3f}–{c['ci95'][1]:.3f} |")
    s = r["ranker_vs_heuristic"]
    lines += ["", f"Ranker against the hand-set score, on the questions where they differ: {s['wins']} won, "
              f"{s['losses']} lost, exact sign test p = {s['p']}.", "", "## Feature importance (gain)", ""]
    lines += [f"- `{k}`: {v:.1f}" for k, v in r["importance"].items()]
    print("\n".join(lines))


if __name__ == "__main__":
    main(sys.argv[1])
